-- Source: MotherDuck thyroid_canonical_publication_v1_0.manuscript_workspace.canonical_path_malignant_events_v1_ete_clean
-- Captured: 2026-05-06 for THY-19 BQ migration

CREATE VIEW manuscript_workspace.canonical_path_malignant_events_v1_ete_clean AS WITH norm AS (SELECT e.*, lower(main."trim"(regexp_replace(COALESCE(e.extrathyroidal_extension, ''), '\s+', ' ', 'g'))) AS _ete_norm FROM main.canonical_path_malignant_events_v1 AS e), graded AS (SELECT n.*, CASE  WHEN (((n._ete_norm = '') OR (n._ete_norm IS NULL))) THEN (NULL) WHEN (((n._ete_norm ~~ '%extensive%') OR (n._ete_norm ~~ '%extesive%'))) THEN ('extensive') WHEN ((n._ete_norm ~~ '%gross%')) THEN ('gross') WHEN (((n._ete_norm ~~ '%microscopic%') OR (n._ete_norm ~~ '%microscopiic%'))) THEN ('microscopic') WHEN ((n._ete_norm ~~ '%minimal%')) THEN ('minimal') WHEN ((n._ete_norm ~~ '%focal%')) THEN ('minimal') WHEN ((n._ete_norm IN ('false', 'no'))) THEN ('none') WHEN ((n._ete_norm IN ('x', '`x', 'c/a', 'n/a', 'indeterminate', '* (see margin comment)'))) THEN (NULL) WHEN (((n._ete_norm ~~ 'yes%') OR (n._ete_norm ~~ 'present%') OR (n._ete_norm ~~ 'true%'))) THEN ('present_unspecified') ELSE NULL END AS ete_grade FROM norm AS n)SELECT g.* EXCLUDE (_ete_norm), g.ete_grade, CASE  WHEN ((g.ete_grade IN ('minimal', 'microscopic'))) THEN ('minimal_microscopic') ELSE g.ete_grade END AS ete_grade_grouped, ((g.gross_ete = 1) AND (g.ete_grade IN ('minimal', 'microscopic', 'present_unspecified'))) AS ete_discordance_flag FROM graded AS g;
